Lemma sows_loop : forall (k i : nat) a7x ra sp gp tp t0 t1 t2 s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m m1 : mem) (C La W : Z) (wbs : list byte),
  (length wbs - i = k)%nat -> (i < length wbs)%nat ->
  rw_cells usegs m1 C [C8 (wz (W + Z.of_nat i))] -> bytes_at usegs m1 W wbs ->
  munch [(C, C + 8)]%Z m m1 -> wmono usegs m m1 -> mem_inv usegs m1 ->
  La = W + Z.of_nat (length wbs) -> La < 2^64 -> (C + 8 <= W \/ W + Z.of_nat (length wbs) <= C) -> 0 < W ->
  evt usegs (sows_post_c (W + Z.of_nat i + Z.of_nat (wspan (skipn i (zbytes wbs))))
               ra sp gp tp t0 t1 t2 s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 F fc C La W wbs m)
    (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (wz C) (wz La) (wz (W + Z.of_nat i)) (wz 32) (wz 1) (wz 9) (wz (W + Z.of_nat i)) a7x
              s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 0x359f8) fc None m1 (seg_rom usegs)).
