(* [comment removed for export] *)
Local Ltac tab_tcharH c :=
  let TB := fresh "TB" in let RD := fresh "RD" in
  lazymatch goal with |- evt _ _ (MS _ _ _ _ _ ?mx _) =>
  lazymatch goal with MI : mem_inv _ mx |- _ =>
    pose proof (tok_tab_bytes mx MI) as TB;
    pose proof (u8ro_read usegs mx TOK_TAB TABB_TCHAR c (Z_to_bv 8 (nth (Z.to_nat c) TAB_IS_TOKEN_CHAR 0)) (Z_to_bv 64 (TOK_TAB + c)) TB
                 (tab_byte TAB_IS_TOKEN_CHAR c len_TCHAR ltac:(lia)) ltac:(lia) ltac:(symmetry; apply wa_of_Z_to_bv; lia)) as RD;
    unfold TOK_TAB in RD;
    step; clear RD TB; rewrite (tchar_load c) by lia; unfold wz
  end end.

Local Ltac list_eq_lia := repeat first [ reflexivity | lia | progress f_equal ].
Local Ltac close_cells OBJ :=
  first [ exact OBJ
        | lazymatch goal with |- rw_cells _ _ _ ?cs2 =>
            lazymatch type of OBJ with rw_cells _ _ _ ?cs1 =>
              replace cs2 with cs1; [exact OBJ | unfold wz; list_eq_lia ] end end ].

