  ltac2:(KReplay.run [|constr:(@Corelib.Init.Datatypes.bool); constr:(@Corelib.Init.Datatypes.nat); constr:(@Corelib.Init.Datatypes.list); constr:(@Corelib.Numbers.BinNums.Z); constr:(@Corelib.Init.Logic.eq); constr:(@OSSVerify.Proofs.boost_beast.http_request.lib.Ub.XP_tok_stmt.tokres); constr:(@OSSVerify.Proofs.boost_beast.http_request.lib.Ub.XP_tok_stmt.tok_next); constr:(@Corelib.Lists.ListDef.skipn); constr:(@OSSVerify.Proofs.boost_beast.http_request.lib.Ub.XP_tok_stmt.tk_shiftn); constr:(@OSSVerify.Proofs.boost_beast.http_request.lib.Ub.XP_tok_stmt.wspan); constr:(@Corelib.Classes.Morphisms.trans_co_eq_inv_impl_morphism); constr:(@OSSVerify.Proofs.boost_beast.http_request.lib.Lib.Cells.cell); constr:(@Corelib.Classes.RelationClasses.eq_Transitive); constr:(@OSSVerify.Proofs.boost_beast.http_request.lib.Ub.XP_tok.HCW.tokit_cells_gen); constr:(@Corelib.Classes.Morphisms.reflexive_proper); constr:(@Corelib.Classes.Morphisms.respectful); constr:(@Corelib.Classes.Morphisms.reflexive_reflexive_proxy); constr:(@Corelib.Classes.Morphisms.reflexive_eq_dom_reflexive); constr:(@Corelib.Classes.RelationClasses.eq_Reflexive); constr:(@Corelib.Classes.Morphisms.eq_proper_proxy); constr:(@Corelib.Init.Nat.add); constr:(@Stdlib.ZArith.BinInt.Z.add); constr:(@Stdlib.ZArith.BinInt.Z.of_nat); constr:(@OSSVerify.Proofs.boost_beast.http_request.lib.Ub.XP_tok_stmt.tok_next_wspan); constr:(@Corelib.Init.Logic.eq_ind_r); constr:(@Corelib.Init.Logic.eq_refl); constr:(@OSSVerify.Proofs.boost_beast.http_request.lib.Ub.XP_tok.HCW.skipn_skipn'); constr:(@OSSVerify.Proofs.boost_beast.http_request.lib.Ub.XP_tok.HCW.tokit_cells_gen_shiftn)|] [|@last; @fst; @cur; @r; @lemma; @l; @s; @i; @nc|] "##n#*#F#0#$#%#&###(#'#2#)#/#6#5#:#A#C#B#E#1#8#9#?#=#;#7#D#F#G#H#.#-#3#4#<#>#@+#A%#/'#B&#C'#D'#E%#4&#4$ULC%CIF#H#UM$%C#%#H#VN%#)J'#ULS%*#US&$%CHI#K#$#FEDUM%%C#&#K#VN%#$#FEDk#$C-k#%C#k#&C#k#'J#*J*C&C3#2&C)$#&C)%#&J)'#US'7'C87#'C.(#'C.(#'J.(#WS(.(#(CF(CE(CDdS)2,&O<7GFF%EE$DD#VPH;%C#I#K#UQ>VRF#$%#ED(s#'#]S*s#(s#'s#&s##>*$$#j#(s#*#VS+Hs#1UQs#0VRE#$s#0#DG)s#.G*j#)s#/#VPIs#5%C#F#KG$#0ED)s#4#0j#)s#=##H'$#-DGVS,s#8#XS-Cs#>IFZS#s#B+'$s#>#$s#=EDGYS.s#As#?EDGZS#s#=20%$#V76#j#$C#j#%C#j#&C#j#*s#J#j#+S/#j#,S0##"). Qed.

Lemma wspan_skip_stop : forall i (s : list Z), (i + wspan (skipn i s) < length s)%nat ->
  is_ws (nth (i + wspan (skipn i s)) s 0) = false.
Proof.
  intros i s H.
  pose proof (wspan_stop (skipn i s)) as W. rewrite length_skipn in W. rewrite nth_skipn in W. apply W. lia.
Qed.

Lemma zbytes_nth : forall (wbs : list byte) j b, nth_error wbs j = Some b -> nth j (zbytes wbs) 0 = zb b.
Proof. intros wbs j b N. apply nth_error_nth. unfold zbytes. rewrite nth_error_map, N. reflexivity. Qed.

Lemma wspan_skip_le : forall i (s : list Z), (i <= length s)%nat -> (i + wspan (skipn i s) <= length s)%nat.
Proof. intros i s Hi. pose proof (wspan_le (skipn i s)) as W. rewrite length_skipn in W. lia. Qed.

Definition tokit_post_c (cells : list cell) (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (A W : Z) (wbs : list byte) (lo : Z) (m : mem) : machine_state -> Prop :=
  fun ms' => exists t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m',
    ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7
                  s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (ret_pc ra) fc None m' (seg_rom usegs)
    /\ munch [(lo, bv_unsigned sp); (A, A + SZ_TOKIT)]%Z m m' /\ wmono usegs m m' /\ mem_inv usegs m'
    /\ stk usegs m' lo (bv_unsigned sp)
    /\ rw_cells usegs m' A cells
    /\ bytes_at usegs m' W wbs.

(* [comment removed for export] *)
Definition utok_ctx (m m1 : mem) (sp s5v s4v s3v s2v s1v s0v rav : word) (A W : Z) (wbs : list byte) (cur fst La lo : Z) (j8 : list byte) : Prop :=
  rw_cells usegs m1 (bv_unsigned sp + -64) [CB 8 j8; C8 s5v; C8 s4v; C8 s3v; C8 s2v; C8 s1v; C8 s0v; C8 rav]
  /\ rw_cells usegs m1 A (TokItCells 0 0 cur fst La)
  /\ bytes_at usegs m1 W wbs
  /\ stk usegs m1 lo (bv_unsigned sp + -64)
  /\ munch [(lo, bv_unsigned sp); (A, A + SZ_TOKIT)]%Z m m1 /\ wmono usegs m m1 /\ mem_inv usegs m1.

Definition utok_pure (sp : word) (A W : Z) (wbs : list byte) (fst La lo : Z) : Prop :=
  La = W + Z.of_nat (length wbs) /\ La < 2^64 /\ 0 <= fst < 2^64
  /\ (A + SZ_TOKIT <= W \/ W + Z.of_nat (length wbs) <= A)
  /\ lo + TOKIT_STACK <= bv_unsigned sp /\ 0xb8000 <= lo
  /\ (bv_unsigned sp <= A \/ A + SZ_TOKIT <= lo) /\ (bv_unsigned sp <= W \/ W + Z.of_nat (length wbs) <= lo)
  /\ ((0 < length wbs)%nat -> 0 < W).

Local Ltac open_uctx CTX PURE :=
  destruct CTX as (FR & OBJ & WIN & ST & MU & WM & MI);
  destruct PURE as (HLA & LA64 & FST & SEP & LO & L98 & SEPA & SEPW & WNZ);
  pose proof (bytes_at_bound _ _ _ _ WIN) as WB;
  pose proof (rw_cells_bound _ _ _ _ OBJ) as OB; cbn [cells_size csize Nat.add TokItCells length] in OB;
  unfold TokItCells, SZ_TOKIT, TOKIT_STACK in *.

Local Ltac rebuild_uctx m sp :=
  try match goal with C : utok_ctx _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ |- _ => clear C end;
  lazymatch goal with |- evt _ _ (MS _ _ _ _ _ ?mx _) =>
  lazymatch goal with
  | FR : rw_cells _ mx (bv_unsigned sp + -64) [CB 8 ?j8; C8 ?s5v; C8 ?s4v; C8 ?s3v; C8 ?s2v; C8 ?s1v; C8 ?s0v; C8 ?rav],
    OBJ : rw_cells _ mx ?A [C8 _; C8 _; C8 (Z_to_bv 64 ?cur); C8 (Z_to_bv 64 ?fst); C8 (Z_to_bv 64 ?La)],
    WIN : bytes_at _ mx ?W ?wbs, ST : stk _ mx ?lo _, MU : munch _ m mx, WM : wmono _ m mx, MI : mem_inv _ mx |- _ =>
      let CTX := fresh "CTX" in
      assert (CTX : utok_ctx m mx sp s5v s4v s3v s2v s1v s0v rav A W wbs cur fst La lo j8)
        by (split; [exact FR | split; [exact OBJ | split; [exact WIN | split; [exact ST | split; [exact MU | split; [exact WM | exact MI]]]]]])
  end end.

(* [comment removed for export] *)
Local Ltac utok_epilogue FR ST OBJ sp :=
  step; step; step; step; step; step; step; step; release_frame FR ST (bv_unsigned sp); step;
  finish; close_cells OBJ.

(* [comment removed for export] *)
Local Ltac call_sows OBJ A cur La W wbs :=
  let O1 := fresh "O1" in let O23 := fresh "O23" in let CELL := fresh "CELL" in let O3 := fresh "O3" in let SS := fresh "SS" in
  lazymatch type of OBJ with rw_cells _ _ _ [?c1; ?c2; ?c3; ?c4; ?c5] =>
    split_frame OBJ [c1; c2] [c3; c4; c5] O1 O23;
    split_frame O23 [c3] [c4; c5] CELL O3
  end;
  pose proof skip_ows_spec as SS; unfold skip_ows_stmt, skip_ows_post, P_UB_SKIP_OWS in SS; unfold wz in SS;
  call (SS (A + 16) cur La W wbs);
  [ exact CELL | fast_assumption | lia | lia | lia | lia | fast_assumption | fast_assumption | ];
  clear SS; try clear CELL;
  try match goal with H : bytes_at _ _ W _, H' : bytes_at _ _ W _ |- _ => clear H' end;
  lazymatch goal with H : bytes_at _ _ W _ |- _ => try rename H into WIN end;
  lazymatch goal with C' : rw_cells _ _ (A + 16) [C8 _] |- _ =>
    join_frame C' O3 (A + 16); join_frame O1 C' A; rename O1 into OBJ
  end.

