(* [comment removed for export] *)
Lemma uincr_loop : forall (mu i : nat) (nc : bool) (fst : Z) a3x a4x a5x a6x a7x rax ra sp gp tp t0 t1 t2 s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m m1 : mem) (A W La lo : Z) (wbs : list byte) (j8 : list byte),
  (length wbs - i < mu)%nat -> (i < length wbs)%nat ->
  (forall b, nth_error wbs i = Some b -> is_ws (zb b) = false) ->
  utok_ctx m m1 sp s5 s4 s3 s2 s1 s0 ra A W wbs (W + Z.of_nat i) fst La lo j8 -> utok_pure sp A W wbs fst La lo ->
  evt usegs (tokit_post_c (tokit_cells_gen (tok_next nc (skipn i (zbytes wbs))) (W + Z.of_nat i) fst La)
               ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc A W wbs lo m)
    (MS (mkR rax (Z_to_bv 64 (bv_unsigned sp + -64)) gp tp t0 t1 t2 (wz A) (wz (A + 16))
              (wz (W + Z.of_nat i)) (wz La) (wz (if nc then 1 else 0)) a3x a4x a5x a6x a7x
              (wz TOK_TAB) (wz 44) (wz NTOK_TAB) (wz 2) s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 0x36d10) fc None m1 (seg_rom usegs)).
