Definition optit_post_c (cells : list cell) (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (A lst SP : Z) (sbs : list byte) (lrest : list cell) (lo : Z) (m : mem) : machine_state -> Prop :=
  fun ms' => exists t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m',
    ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7
                  s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (ret_pc ra) fc None m' (seg_rom usegs)
    /\ munch [(lo, bv_unsigned sp); (A, A + SZ_TOKIT)]%Z m m' /\ wmono usegs m m' /\ mem_inv usegs m'
    /\ stk usegs m' lo (bv_unsigned sp)
    /\ rw_cells usegs m' A cells
    /\ rw_cells usegs m' lst (C8 (wz SP) :: C8 (wz (Z.of_nat (length sbs))) :: lrest)
    /\ bytes_at usegs m' SP sbs.

Lemma optit_incr_post_c : forall ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc A lst it err SP pad7 sbs lrest lo m,
  optit_incr_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc A lst it err SP pad7 sbs lrest lo m
  = optit_post_c (optit_cells_after (tok_next (negb (it =? SP)) (tok_suffix SP it sbs)) lst it err pad7)
      ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc A lst SP sbs lrest lo m.
Proof. intros. reflexivity. Qed.

Definition uopt_ctx (m m1 : mem) (sp s6v s5v s4v s3v s2v s1v s0v rav : word) (A lst SP : Z) (sbs : list byte) (lrest : list cell)
    (cur err : Z) (pad7 : list byte) (lo : Z) : Prop :=
  rw_cells usegs m1 (bv_unsigned sp + -64) [C8 s6v; C8 s5v; C8 s4v; C8 s3v; C8 s2v; C8 s1v; C8 s0v; C8 rav]
  /\ rw_cells usegs m1 A (OptItCells lst cur 0 0 err pad7)
  /\ rw_cells usegs m1 lst (C8 (wz SP) :: C8 (wz (Z.of_nat (length sbs))) :: lrest)
  /\ bytes_at usegs m1 SP sbs
  /\ stk usegs m1 lo (bv_unsigned sp + -64)
  /\ munch [(lo, bv_unsigned sp); (A, A + SZ_TOKIT)]%Z m m1 /\ wmono usegs m m1 /\ mem_inv usegs m1.

Definition uopt_pure (sp : word) (A lst SP : Z) (sbs : list byte) (lrest : list cell) (lo : Z) : Prop :=
  SP + Z.of_nat (length sbs) < 2^64
  /\ (A + SZ_TOKIT <= SP \/ SP + Z.of_nat (length sbs) <= A)
  /\ (A + SZ_TOKIT <= lst \/ lst + Z.of_nat (cells_size (C8 (wz SP) :: C8 (wz (Z.of_nat (length sbs))) :: lrest)) <= A)
  /\ lo + TOKIT_STACK <= bv_unsigned sp /\ 0xb8000 <= lo
  /\ (bv_unsigned sp <= A \/ A + SZ_TOKIT <= lo) /\ (bv_unsigned sp <= SP \/ SP + Z.of_nat (length sbs) <= lo)
  /\ (bv_unsigned sp <= lst \/ lst + Z.of_nat (cells_size (C8 (wz SP) :: C8 (wz (Z.of_nat (length sbs))) :: lrest)) <= lo)
  /\ ((0 < length sbs)%nat -> 0 < SP).

Local Ltac open_octx CTX PURE :=
  destruct CTX as (FR & OBJ & LSV & WIN & ST & MU & WM & MI);
  destruct PURE as (SP64 & SEP & SEPL & LO & L98 & SEPA & SEPW & SEPLS & WNZ);
  pose proof (bytes_at_bound _ _ _ _ WIN) as WB;
  pose proof (rw_cells_bound _ _ _ _ OBJ) as OB; cbn [cells_size csize Nat.add OptItCells length] in OB;
  pose proof (rw_cells_bound _ _ _ _ LSV) as LB; cbn [cells_size csize Nat.add length] in LB, SEPL, SEPLS;
  unfold OptItCells, SZ_TOKIT, TOKIT_STACK in *.

Local Ltac rebuild_octx m sp :=
  try match goal with C : uopt_ctx _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ |- _ => clear C end;
  lazymatch goal with |- evt _ _ (MS _ _ _ _ _ ?mx _) =>
  lazymatch goal with
  | FR : rw_cells _ mx (bv_unsigned sp + -64) [C8 ?s6v; C8 ?s5v; C8 ?s4v; C8 ?s3v; C8 ?s2v; C8 ?s1v; C8 ?s0v; C8 ?rav],
    OBJ : rw_cells _ mx ?A [C8 (Z_to_bv 64 ?lst); C8 (Z_to_bv 64 ?cur); C8 _; C8 _; C1 (b8 ?err); CB 7 ?pad7],
    LSV : rw_cells _ mx ?lst' (C8 (Z_to_bv 64 ?SP) :: C8 _ :: ?lrest),
    WIN : bytes_at _ mx ?SP' ?sbs, ST : stk _ mx ?lo _, MU : munch _ m mx, WM : wmono _ m mx, MI : mem_inv _ mx |- _ =>
      let CTX := fresh "CTX" in
      assert (CTX : uopt_ctx m mx sp s6v s5v s4v s3v s2v s1v s0v rav A lst SP sbs lrest cur err pad7 lo)
        by (split; [exact FR | split; [exact OBJ | split; [exact LSV | split; [exact WIN | split; [exact ST | split; [exact MU | split; [exact WM | exact MI]]]]]]])
  end end.

(* [comment removed for export] *)
Local Ltac uopt_epilogue FR ST OBJ sp :=
  step; step; step; step; step; step; step; step; step; release_frame FR ST (bv_unsigned sp); step;
  finish; close_cells OBJ.

(* [comment removed for export] *)
Local Ltac call_sows_opt OBJ A cur La W wbs :=
  let O1 := fresh "O1" in let O23 := fresh "O23" in let CELL := fresh "CELL" in let O3 := fresh "O3" in let SS := fresh "SS" in
  lazymatch type of OBJ with rw_cells _ _ _ [?c1; ?c2; ?c3; ?c4; ?c5; ?c6] =>
    split_frame OBJ [c1] [c2; c3; c4; c5; c6] O1 O23;
    split_frame O23 [c2] [c3; c4; c5; c6] CELL O3
  end;
  pose proof skip_ows_spec as SS; unfold skip_ows_stmt, skip_ows_post, P_UB_SKIP_OWS in SS; unfold wz in SS;
  call (SS (A + 8) cur La W wbs);
  [ exact CELL | fast_assumption | lia | lia | lia | lia | fast_assumption | fast_assumption | ];
  clear SS; try clear CELL;
  try match goal with H : bytes_at _ _ W _, H' : bytes_at _ _ W _ |- _ => clear H' end;
  lazymatch goal with H : bytes_at _ _ W _ |- _ => try rename H into WIN end;
  lazymatch goal with C' : rw_cells _ _ (A + 8) [C8 _] |- _ =>
    join_frame C' O3 (A + 8); join_frame O1 C' A; rename O1 into OBJ
  end.

(* [comment removed for export] *)
Lemma uopt_end : forall (cur : Z) rax a0x a1x a2x a3x a4x a5x a6x a7x s3x s4x s5x s6x ra sp gp tp t0 t1 t2 s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m m1 : mem) (A lst SP err lo : Z) (sbs : list byte) (lrest : list cell) (pad7 : list byte),
  uopt_ctx m m1 sp s6 s5 s4 s3 s2 s1 s0 ra A lst SP sbs lrest cur err pad7 lo -> uopt_pure sp A lst SP sbs lrest lo ->
