Lemma uopt_tok : forall (k i j : nat) (itv err : Z) a4x a5x a6x a7x s4x s5x s6x rax ra sp gp tp t0 t1 t2 s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m m1 : mem) (A lst SP lo : Z) (sbs : list byte) (lrest : list cell) (pad7 : list byte),
  (length sbs - j = k)%nat -> (i < j)%nat -> (j <= length sbs)%nat ->
  uopt_ctx m m1 sp s6 s5 s4 s3 s2 s1 s0 ra A lst SP sbs lrest itv err pad7 lo -> uopt_pure sp A lst SP sbs lrest lo ->
  evt usegs (optit_post_c (OptItCells lst (SP + Z.of_nat (j + tspan (skipn j (zbytes sbs)))) (SP + Z.of_nat i)
                                       (Z.of_nat (j - i + tspan (skipn j (zbytes sbs)))) err pad7)
               ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc A lst SP sbs lrest lo m)
    (MS (mkR rax (Z_to_bv 64 (bv_unsigned sp + -64)) gp tp t0 t1 t2 (wz A) (wz (SP + Z.of_nat (length sbs)))
              (wz (SP + Z.of_nat i)) (wz (SP + Z.of_nat j)) (wz 2) (wz (SP + Z.of_nat j - 1)) a4x a5x a6x a7x
              (wz (A + 8)) (wz TOK_TAB) s4x s5x s6x s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 0x403ac) fc None m1 (seg_rom usegs)).
