(* [comment removed for export] *)
Lemma uopt_loop : forall (mu i : nat) (nc : bool) (err : Z) a2x a3x a4x a5x a6x a7x rax ra sp gp tp t0 t1 t2 s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m m1 : mem) (A lst SP lo : Z) (sbs : list byte) (lrest : list cell) (pad7 : list byte),
  (length sbs - i < mu)%nat -> (i < length sbs)%nat ->
  (forall b, nth_error sbs i = Some b -> is_ws (zb b) = false) ->
  uopt_ctx m m1 sp s6 s5 s4 s3 s2 s1 s0 ra A lst SP sbs lrest (SP + Z.of_nat i) err pad7 lo -> uopt_pure sp A lst SP sbs lrest lo ->
  evt usegs (optit_post_c (optit_cells_after (tok_next nc (skipn i (zbytes sbs))) lst (SP + Z.of_nat i) err pad7)
               ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc A lst SP sbs lrest lo m)
    (MS (mkR rax (Z_to_bv 64 (bv_unsigned sp + -64)) gp tp t0 t1 t2 (wz A) (wz (SP + Z.of_nat (length sbs)))
              (wz (SP + Z.of_nat i)) (wz (if nc then 1 else 0)) a2x a3x a4x a5x a6x a7x
              (wz (A + 8)) (wz TOK_TAB) (wz 44) (wz NTOK_TAB) (wz 2) s7 s8 s9 s10 s11 t3 t4 t5 t6)
